// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // After calling NETM(), owner has balance = totalDistributed = 250000000e18
        vm.prank(address(c)); // prank doesn't matter for NETM() but call it as someone
        c.NETM();
        address owner = address(c); // get owner address (a contract)
        uint256 balance = c.balanceOf(owner); // should be 250000000e18
        // Now try to transfer the exact balance to another address
        bool ok;
        vm.prank(owner);
        try c.transfer(address(0xdead), balance) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference passes (ok = true), buggy fails (ok = false)
        assertTrue(ok == true); // This assertion holds on reference, fails on buggy
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Step 1: Call NETM() as owner to set balances[owner] = totalDistributed
        vm.prank(c.owner());
        c.NETM();

        // Step 2: Owner approves self to spend 2 tokens
        address owner = c.owner();
        vm.prank(owner);
        c.approve(owner, 2);

        // Step 3: Owner calls transferFrom(owner, someone, 2)
        address someone = address(0x1234);
        vm.prank(owner);
        c.transferFrom(owner, someone, 2);

        // Assert: allowance should be 0 (reference) vs 1 (buggy) because bug deducts amount-1
        uint256 remaining = c.allowance(owner, owner);
        // Reference: 2 - 2 = 0, Bug: 2 - (2-1) = 1
        assertTrue(remaining == 0, "Bug allows leftover allowance");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address owner = address(0x1);
        address spender = address(0x2);
        address to = address(0x3);

        vm.prank(owner);
        c.NETM();

        vm.prank(owner);
        c.approve(spender, 1);

        vm.prank(spender);
        bool ok;
        try c.transferFrom(owner, to, 1) {
            ok = true;
        } catch {
            ok = false;
        }

        // After first transferFrom(owner, to, 1):
        // Reference: allowance becomes 0, second call should revert
        // Buggy: allowance becomes 1, second call succeeds

        // Attempt second transferFrom with amount 1
        vm.prank(spender);
        bool ok2;
        try c.transferFrom(owner, to, 1) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        assertTrue(ok); // first call succeeds in both
        assertTrue(ok2 == false); // second call must revert in reference, but succeeds in bug
    }
}

