pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testRegression_property() public {
        // Step 0: Make the owner call NETM() to initialize balances
        address owner = address(this);
        c.NETM();

        // Step 1: First investor (alice) calls getTokens() - succeeds
        address alice = address(0x1111);
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.getTokens{value: 0}();

        // In reference: alice is now blacklisted
        // In buggy: alice is NOT blacklisted

        // Step 2: Second investor (bob) tries getTokens()
        address bob = address(0x2222);
        vm.deal(bob, 1 ether);
        vm.prank(bob);
        // This will revert in reference (bob not blacklisted yet) but succeed in buggy
        // We need to observe the difference: after bob's call, check totalDistributed
        // In reference: bob's call reverts, totalDistributed unchanged (still = totalDistributed after alice)
        // In buggy: bob's call succeeds, totalDistributed increases

        // To capture the revert, we try-catch
        bool bobSucceeded;
        try c.getTokens{value: 0}() { bobSucceeded = true; } catch { bobSucceeded = false; }

        // Now check a public getter that differs: totalDistributed
        // In reference: bob's call reverted, totalDistributed = 250000000e18 + value_after_alice
        // In buggy: bob's call succeeded, totalDistributed = that plus another value
        // The exact values are deterministic; we just need to assert something that differs
        uint256 td = c.totalDistributed();
        // The buggy version will have larger totalDistributed (since bob succeeded)
        // In reference: bob reverted, so totalDistributed is smaller
        // Thus assert: if bob succeeded (buggy), td is larger than some threshold
        // We compute the precise expected value for the reference:
        uint256 firstValue = 2500e18; // value at start
        if (firstValue > c.totalRemaining()) { firstValue = c.totalRemaining(); }
        uint256 referenceAfterAlice = 250000000e18 + firstValue;
        uint256 secondValue = (firstValue / 100000) * 99999;
        // In buggy, bob succeeds: secondValue is added to totalDistributed
        // In reference, bob fails: nothing added

        // The assertion: if bobSucceeded, then totalDistributed > referenceAfterAlice
        // This is true only in buggy version
        if (bobSucceeded) {
            assertTrue(td > referenceAfterAlice, "Buggy: bob succeeded, totalDistributed larger");
        } else {
            // In reference, totalDistributed equals referenceAfterAlice
            assertTrue(td == referenceAfterAlice, "Reference: bob failed, totalDistributed unchanged");
        }
    }
}

