pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Record the initial totalRemaining (which = totalSupply - totalDistributed = 250000000e18)
        uint256 initialTotalRemaining = c.totalRemaining();
        // Call NETM() - onlyOwner, so prank as deployer (default msg.sender = address(this))
        vm.prank(address(this));
        c.NETM();
        // In reference: totalRemaining decreased by totalDistributed (250000000e18)
        // In bug: totalRemaining unchanged
        uint256 expectedTotalRemaining = initialTotalRemaining - 250000000e18;
        assertTrue(c.totalRemaining() == expectedTotalRemaining, "totalRemaining should be decreased by totalDistributed after NETM");
    }
}

