        vm.prank(address(this));
        c.NETM();

        // Now totalRemaining = totalSupply - totalDistributed = 250000000e18
        // value = 2500e18, blacklist[alice] == false
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.getTokens{value: 0}();

        // After getTokens, value becomes oldValue * 99999 / 100000 = 2499.975e18 (truncated)
        // totalRemaining in reference decreased by 2500e18, buggy unchanged
        // totalRemaining in reference = 250000000e18 - 2500e18 = 249997500e18
        // value now = 2499.975e18 * 1e18 / 1e18 (approx 2499.975e18)
        // totalRemaining > value, so no revert yet

        // To force revert on reference (buggy succeeds), we need to drain totalRemaining
        // We'll make alice call again, but value changes each call
        // Let's compute: after first call, value = (2500e18 / 100000) * 99999 = 2499975000000000000000000000000000 / 100000? Wait, careful.
        // Actually (value / 100000) is integer division, so 2500e18 / 100000 = 25e15 (since 2500e18 / 100000 = 0.025e18 = 25e15)
        // Then * 99999 = 25e15 * 99999 = 2499975e15 = 2.499975e21 = 2499.975e18
        // So new value = 2499.975e18
        // totalRemaining reference = 250000000e18 - 2500e18 = 249997500e18?
        // 250000000e18 - 2500e18 = 249997500e18
        // But value = 2499.975e18, so totalRemaining is still huge.

