// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Call NETM() which is public onlyOwner; prank as owner
        vm.prank(address(this));
        c.NETM();
        // After NETM(): balances[owner] = 250000000e18, totalDistributed unchanged (initially 250000000e18),
        // totalRemaining = totalSupply - totalDistributed = 500000000e18 - 250000000e18 = 250000000e18 in reference
        // In mutant, totalRemaining was set to 0 before subtraction, then 0 - _amount underflows (but SafeMath.sub not used here)
        // Actually the line totalRemaining = totalRemaining - (_amount) uses regular subtraction which underflows and reverts.
        // So mutant reverts on NETM() call; we need to catch revert.
        bool ok;
        try c.NETM() {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: NETM() does not revert (totalRemaining updated correctly). 
        // Mutant: NETM() reverts due to underflow because totalRemaining was set to 0.
        // We call NETM() once more to test: after first successful NETM() in reference, state is as above.
        // In mutant, first NETM() reverts, so c.state is unchanged.
        // We observe whether a second NETM() call reverts. In reference, second call would succeed (balance > 0).
        // In mutant, first call already reverted, state unchanged so second call also reverts.
        // Simpler: just test the first call revert behavior.
        vm.prank(address(this));
        bool revertHappens = false;
        try c.NETM() {
            revertHappens = false;
        } catch {
            revertHappens = true;
        }
        // In reference, NETM() should succeed without revert (revertHappens == false).
        // In mutant, NETM() reverts due to underflow (revertHappens == true).
        // But wait: after setUp() we already called NETM() above? No, setUp() only deploys.
        // We call once in this test.
        // Actually let's simplify: after first call, check totalRemaining public getter.
        // Reset state: deploy new C in test body? No, setUp() deploys one.
        // Let's redo: call NETM() once, then check totalRemaining.
        // Re-deploy inside test to have fresh initial state.
        C c2 = new C();
        vm.prank(address(this));
        c2.NETM();
        uint256 tr = c2.totalRemaining();
        // Reference: totalRemaining = 250000000e18
        // Mutant: totalRemaining = 0 (because set to 0 at start of distr, then after subtraction? Actually mutant also has totalRemaining = totalRemaining - _amount where totalRemaining is 0, so underflow revert.
        // But if it didn't revert, it would be 0. Let's just check.
        assertTrue(tr == 250000000e18 || tr == 0, "totalRemaining differs");
    }
}

