        // Call NETM() as owner to initialize balances and totalDistributed
        vm.prank(c.owner());
        c.NETM();

        // Record totalRemaining after NETM()
        uint256 totalRemainingAfterNETM = c.totalRemaining();

        // Now a non-blacklisted user calls getTokens() to trigger distr
        address user = address(0x1234);
        vm.deal(user, 1 ether);
        vm.prank(user);
        c.getTokens();

        // After getTokens(), totalRemaining should have decreased by value (which equals totalRemaining at that point)
        // In the correct contract, totalRemaining becomes 0.
        // In the buggy contract, totalRemaining stays the same because the update is missing.
        uint256 totalRemainingAfterGetTokens = c.totalRemaining();

        // The correct contract: totalRemaining decreases to 0 (since value == totalRemaining)
        // The buggy contract: totalRemaining unchanged.
        // We assert that totalRemainingAfterGetTokens is less than totalRemainingAfterNETM.
        // For the correct contract this holds; for the buggy contract it fails.
        assertTrue(totalRemainingAfterGetTokens < totalRemainingAfterNETM);
    }
}

